SELECT TIMESTAMP '2001-02-16 20:38:40' AT LOCAL;

SELECT TIMESTAMP WITH TIME ZONE '2001-02-16 20:38:40-05' AT LOCAL;

SELECT TIME WITH TIME ZONE '20:38:40-05' AT LOCAL;

SELECT '2001-02-16 20:38:40'::timestamptz AT LOCAL;

SELECT created_at AT TIME ZONE 'UTC' AT LOCAL FROM events;

SELECT (created_at AT LOCAL)::date FROM events;
